use std::fs

fn all_digits(s: string) -> bool {
    if s.len() == 0 { return false }
    for c in s.chars() {
        if c < '0' || c > '9' { return false }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut users: Vec<string> = []
    let mut counts: Vec<int> = []
    let mut totals: Vec<int> = []
    let mut akeys: Vec<string> = []
    let mut auser: Vec<int> = []
    let mut aname: Vec<string> = []
    let mut acnt: Vec<int> = []
    let mut bad = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            bad += 1
            continue
        }
        let secs: int = parts[2].parse::<int>().unwrap_or(0)
        let mut ui: int = -1
        let mut i: int = 0
        while i < users.len() as int {
            if users[i as usize] == parts[0] { ui = i }
            i += 1
        }
        if ui < 0 {
            users.push(parts[0])
            counts.push(0)
            totals.push(0)
            ui = users.len() as int - 1
        }
        counts[ui as usize] = counts[ui as usize] + 1
        totals[ui as usize] = totals[ui as usize] + secs
        let mut ai: int = -1
        let mut j: int = 0
        while j < aname.len() as int {
            if auser[j as usize] == ui && aname[j as usize] == parts[1] { ai = j }
            j += 1
        }
        if ai < 0 {
            auser.push(ui)
            aname.push(parts[1])
            acnt.push(1)
        } else {
            acnt[ai as usize] = acnt[ai as usize] + 1
        }
    }
    let n: int = users.len() as int
    let mut order: Vec<int> = []
    let mut k: int = 0
    while k < n {
        order.push(k)
        k += 1
    }
    // insertion sort
    let mut a: int = 1
    while a < n {
        let mut b: int = a
        while b > 0 {
            let x = order[(b - 1) as usize]
            let y = order[b as usize]
            let mut swap = false
            if totals[y as usize] > totals[x as usize] { swap = true }
            if totals[y as usize] == totals[x as usize] && users[y as usize] < users[x as usize] { swap = true }
            if !swap { break }
            order[(b - 1) as usize] = y
            order[b as usize] = x
            b -= 1
        }
        a += 1
    }
    for u in order {
        let mut best = ""
        let mut bc = 0
        let mut j: int = 0
        while j < aname.len() as int {
            if auser[j as usize] == u {
                let c = acnt[j as usize]
                if c > bc || (c == bc && aname[j as usize] < best) {
                    bc = c
                    best = aname[j as usize]
                }
            }
            j += 1
        }
        println("${users[u as usize]} ${counts[u as usize]} ${totals[u as usize]} ${best}")
    }
    println("malformed: ${bad}")
}

